  '书之世界': { zh: { core: '书之世界', detail: '由书籍与纸张构成的世界，纸制景观，巨型书本，充满想象力，漂浮的书页，墨水画，纸树，文字与字母' } },
  '时钟王国': { zh: { core: '时钟王国', detail: '钟表与时间的王国，巨型时钟，转动齿轮，机械鸟，黄铜与黄金，滴答作响，华丽机构，蒸汽朋克优雅' } },
  '蒸汽飞艇': { zh: { core: '蒸汽飞艇', detail: '漂浮在天空的华丽蒸汽飞艇，黄铜与铜制船体，巨型螺旋桨，蒸汽喷口，帆布船帆，云层在下方，充满冒险气息' } },
